# THE UNICODE MAP (since R1c): how the reader classifies a code point. pl-umap.c is GENERATED
# upstream (Unicode/prolog_syntax_map.pl, from the Unicode data files); its tables are carried over
# as data, byte for byte, by tools/gen_umap.jl, which rewrites the region between the markers below.
# The functions after the region are ported by hand.
#
# A map (`uflags_map`, `uctype_map`) holds a page's number in its pages (`_uflags_map_pages`,
# `_uctype_map_pages`), or -1 - b for a page whose every entry is the byte b (see `uflagsRaw`).
# The pages and the maps are Strings, the small tables tuples: the kernel keeps no mutable state at
# module level (tools/lint_globals.jl).
# NOT PORTED: the case tables (`case_deltas`, `pl_case_runs`, `pl_case_titles`) and their functions
# (`pl_toupper`, `pl_tolower`, `pl_totitle`), with their first reader (`upcase_atom/2`, …).

# ── GENERATED by tools/gen_umap.jl from pl-umap.c — do not edit up to END GENERATED ──
#! format: off
const UNICODE_MAP_SIZE = 4353

# The syntax category in bits 0..3 of a `uflags_map` entry (pl-umap.c `u_category`).
@enum u_category::UInt8 begin
    U_CAT_OTHER = 0
    U_CAT_LAYOUT = 1
    U_CAT_SOLO = 2
    U_CAT_BRACKET = 3
    U_CAT_QUOTE = 4
    U_CAT_ID_CONTINUE = 5
    U_CAT_ID_START_ATOM = 6
    U_CAT_ID_START_VARIABLE = 7
    U_CAT_DECIMAL = 8
    U_CAT_SYMBOL = 9
    U_CAT_ID_CONTINUE_SOLO = 10
    U_CAT_PATTERN_SYNTAX = 11
end

