# The `cp`th entry of a map, an Int16 stored little-endian in the String `m`.
@inline _map_entry(m::String, cp::Int)::Int16 =
    reinterpret(Int16, UInt16(codeunit(m, 2cp + 1)) | (UInt16(codeunit(m, 2cp + 2)) << 8))

# PORT: pl-umap.c uflagsRaw
# DIVERGES: the map holds a page's number in `_uflags_map_pages`, or -1 - b for a page whose every
# entry is the byte b, where upstream holds a pointer to the page or the byte cast to one (`F(b)`);
# the map and the pages are Strings.
"The map entry of `code`: its category and display width (pl-umap.c); 0 outside the map."
function uflagsRaw(code::Int)::UInt8
    cp = Int((code % UInt32) ÷ UInt32(256))         # (unsigned)code / 256
    if cp < UNICODE_MAP_SIZE
        s = _map_entry(uflags_map, cp)
        s < 0 && return UInt8(-1 - s)               # a page of one byte, F(b)
        return codeunit(_uflags_map_pages, Int(s) * 256 + (code & 0xff) + 1)
    end
    return 0x00
end

